{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-tLx3ps/src/address.js","content":"/**
 * Cell-address helpers: parsing, validation, column<->number conversion,
 * and range expansion (in column-major, ascending order).
 */

const ADDR_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Column letters -> 1-based number (A=1 ... Z=26, AA=27 ... ZZ=702). */
export function colNumber(colStr) {
  const upper = colStr.toUpperCase()
  let n = 0
  for (const ch of upper) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

/** 1-based number -> column letters (inverse of colNumber). */
export function numberToCol(value) {
  if (value <= 26) return String.fromCharCode(64 + value)
  const m = value - 27
  const a = Math.floor(m / 26) + 1
  const b = (m % 26) + 1
  return String.fromCharCode(64 + a) + String.fromCharCode(64 + b)
}

/**
 * Parse a candidate address (already or not yet upper-cased). Returns
 * { col, row, key } when the text is one or two letters and one to three
 * digits naming a row of at least 1, and null otherwise.
 */
export function parseAddress(text) {
  const m = ADDR_RE.exec(text)
  if (!m) return null
  const col = m[1].toUpperCase()
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  return { col, row, key: col + row }
}

/** Compare two canonical address keys (e.g. "A1", "AA23") for sort order. */
export function compareAddrKeys(a, b) {
  const pa = parseAddress(a)
  const pb = parseAddress(b)
  const ca = colNumber(pa.col)
  const cb = colNumber(pb.col)
  if (ca !== cb) return ca - cb
  return pa.row - pb.row
}

/**
 * Expand a range given its two corner texts (raw, case-insensitive) into a
 * list of { col, row, key } in ascending column then ascending row order.
 * Returns null when either corner is not a valid address.
 */
export function expandRangeAddrs(fromText, toText) {
  const a = parseAddress(fromText)
  const b = parseAddress(toText)
  if (!a || !b) return null
  const c1 = colNumber(a.col)
  const c2 = colNumber(b.col)
  const cMin = Math.min(c1, c2)
  const cMax = Math.max(c1, c2)
  const rMin = Math.min(a.row, b.row)
  const rMax = Math.max(a.row, b.row)
  const out = []
  for (let c = cMin; c <= cMax; c++) {
    const col = numberToCol(c)
    for (let r = rMin; r <= rMax; r++) {
      out.push({ col, row: r, key: col + r })
    }
  }
  return out
}
"}

