chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-tLx3ps/src/values.js","content":"/**
 * Value model: a value is a number, text, a boolean, or an error.
 * Represented as a tagged object { t: 'num'|'text'|'bool'|'err', v }.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function NUM(v) {
  return { t: 'num', v }
}
export function TXT(v) {
  return { t: 'text', v }
}
export function BOOL(v) {
  return { t: 'bool', v }
}
export function ERR(v) {
  return { t: 'err', v }
}

const LITERAL_NUM_RE = /^-?[0-9]+(\.[0-9]+)?$/

export function parseLiteral(content) {
  if (content === '') return NUM(0)
  if (LITERAL_NUM_RE.test(content)) return NUM(parseFloat(content))
  if (ERROR_TOKENS.includes(content)) return ERR(content)
  return TXT(content)
}

/** Read a value as a number for arithmetic: bool -> 1/0, text -> #VALUE!, error/number pass through. */
export function toNumber(v) {
  if (v.t === 'err') return v
  if (v.t === 'num') return v
  if (v.t === 'bool') return NUM(v.v ? 1 : 0)
  return ERR('#VALUE!')
}
"}

