{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-tLx3ps/src/lexer.js","content":"/**
 * Tokenizer for a formula body (the text after the leading `=`).
 * Returns null when it encounters a character the grammar cannot use.
 */

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const c = src[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (c >= '0' && c <= '9') {
      let j = i + 1
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      if (src[j] === '.' && j + 1 < n && src[j + 1] >= '0' && src[j + 1] <= '9') {
        let k = j + 1
        while (k < n && src[k] >= '0' && src[k] <= '9') k++
        tokens.push({ type: 'NUM', value: parseFloat(src.slice(i, k)) })
        i = k
        continue
      }
      tokens.push({ type: 'NUM', value: parseFloat(src.slice(i, j)) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      let j = i + 1
      while (j < n && /[A-Za-z0-9]/.test(src[j])) j++
      tokens.push({ type: 'WORD', value: src.slice(i, j) })
      i = j
      continue
    }
    if (c === '(') {
      tokens.push({ type: 'LP' })
      i++
      continue
    }
    if (c === ')') {
      tokens.push({ type: 'RP' })
      i++
      continue
    }
    if (c === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    if (c === ',') {
      tokens.push({ type: 'COMMA' })
      i++
      continue
    }
    if (c === '^' || c === '*' || c === '/' || c === '+' || c === '-' || c === '=') {
      tokens.push({ type: 'OP', value: c })
      i++
      continue
    }
    if (c === '<') {
      if (src[i + 1] === '>') {
        tokens.push({ type: 'OP', value: '<>' })
        i += 2
      } else if (src[i + 1] === '=') {
        tokens.push({ type: 'OP', value: '<=' })
        i += 2
      } else {
        tokens.push({ type: 'OP', value: '<' })
        i++
      }
      continue
    }
    if (c === '>') {
      if (src[i + 1] === '=') {
        tokens.push({ type: 'OP', value: '>=' })
        i += 2
      } else {
        tokens.push({ type: 'OP', value: '>' })
        i++
      }
      continue
    }
    return null
  }
  return tokens
}
"}

