chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-tLx3ps/src/sheet.js","content":"/**
 * Parses the sheet text format into a Map from canonical address key to cell.
 */

import { parseAddress } from './address.js'
import { parseFormula } from './parser.js'
import { parseLiteral } from './values.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const sheet = new Map()

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const raw = lines[idx]
    const trimmed = raw.replace(/^[ \t]+/, '')
    if (trimmed === '' || trimmed[0] === '#') continue

    const wsMatch = /[ \t]/.exec(trimmed)
    const addrEnd = wsMatch ? wsMatch.index : trimmed.length
    const addrText = trimmed.slice(0, addrEnd)
    const rest = trimmed.slice(addrEnd)
    const content = rest.replace(/^[ \t]+/, '')

    const upperAddr = addrText.toUpperCase()
    const addr = parseAddress(upperAddr)
    if (!addr) {
      throw new SheetError(lineNo, `invalid cell address ${upperAddr}`)
    }
    if (sheet.has(addr.key)) {
      throw new SheetError(lineNo, `cell ${addr.key} is declared twice`)
    }

    let cell
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      cell = { addr, content, kind: 'formula', ast }
    } else {
      cell = { addr, content, kind: 'literal', literalValue: parseLiteral(content) }
    }
    sheet.set(addr.key, cell)
  }

  return sheet
}
"}

