import fs from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { compareAddrKeys } from './address.js'
import { makeEvaluator } from './evaluator.js'
import { formatValue } from './format.js'
import { collectDeps } from './deps.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function readStdin() {
  try {
    return fs.readFileSync(0, 'utf8')
  } catch (e) {
    return ''
  }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('error: usage: cli.js values|deps')
    return
  }
  const mode = args[0]
  const input = readStdin()

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`error: line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const keys = [...sheet.keys()].sort(compareAddrKeys)
  let out = ''

  if (mode === 'values') {
    const evaluator = makeEvaluator(sheet)
    for (const key of keys) {
      out += `${key}=${formatValue(evaluator.evalCell(key))}\n`
    }
  } else {
    for (const key of keys) {
      const cell = sheet.get(key)
      const deps = collectDeps(cell)
      const suffix = deps.map((d) => ' ' + d).join('')
      out += `${key}:${suffix}\n`
    }
  }

