function compareCodePoints(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const pa = ca[i].codePointAt(0)
    const pb = cb[i].codePointAt(0)
    if (pa !== pb) return pa < pb ? -1 : 1
  }
  if (ca.length !== cb.length) return ca.length < cb.length ? -1 : 1
  return 0
}

function compareValues(a, b) {
  const ra = rankOf(a)
  const rb = rankOf(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.t === 'num') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'text') return compareCodePoints(a.v, b.v)
  // bool: false below true
  if (a.v === b.v) return 0
  return a.v ? 1 : -1
